input.sparql:
SELECT ?zone ?sensor ?timeseries_id WHERE {
  VALUES ?zoneNameList {('Core_mid' 'Perimeter_mid_ZN_3' 'Perimeter_top_ZN_3')}
  VALUES ?classNameList {('AirTerminal:DualDuct:VAV:Reheat' 'ZoneHVAC:WaterToAirHeatPump')}
  VALUES ?quantityList {('POWER' 'ELECTRICAL_POWER')}
  VALUES ?unitList {('W' 'kW')}
  ?zone brick:hasPoint ?sensor ;
    brick:nome ?zoneName ;
    a ?zoneClass .
  ?sensor brick:isPointOf ?zone ;
    brick:hasQuantity ?quantity ;
    brick:hasUnit ?unit ;
    ref:hasTimeseriesId ?timeseries_id .
  FILTER ( ?zoneName = ANY ?zoneNameList )
  FILTER ( rdf:type_of(?zoneClass) = ANY ?classNameList )
  FILTER ( ?quantity = ANY ?quantityList )
  FILTER ( ?unit = ANY ?unitList )
}
